head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > onviewchange]<br/>Textarea 컴포넌트에서 사용자 조작으로 값이 변경되면 발생합니다.",
    "validation" : [
        "Textarea 컴포넌트에서 사용자 조작으로 값이 변경되면 onviewchange 이벤트가 발생합니다.",
        "setValue() 메소드에 의한 값 변경 시에는 onviewchange 이벤트가 발생하지 않습니다.",
        "info 객체로 변경 전후 값(oldValue, newValue) 이 핸들러에 전달됩니다.",
        "포커스 아웃 시 값 변경이 있으면 'onchange -> onviewchange -> onafterblur' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        initValue: "old",
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onafterblur"])

    // comp 생성 함수 호출
    $c.gcm.createBasicTextArea(cList, eList);
}



// setValue 메소드 호출 (setValue 에 의한 값 변경 시 onviewchange 미발생 검증)
scwin.btn_setValue_onclick = function (e) {
    target1.setValue("setValue");
};



scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange 이벤트 발생=====");
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}



scwin.target1_onafterblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onafterblur 이벤트 발생=====");
}
